// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait PowerManagementAssessmentOwner_supervisor_process_power_management_assessment_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_management_assessment)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_management_assessment)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_management_assessment)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_management_assessment)
  }

  /** helper function to set the values of all input ports.
   * @param power_evidence payload for data port power_evidence
   */
  def put_concrete_inputs(power_evidence : Power_Propulsion_Availability_Supervisor.PowerEvidence): Unit = {
    put_power_evidence(power_evidence)
  }


  /** helper function to check PowerManagementAssessmentOwner_supervisor_process_power_management_assessment's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param power_assessment method that will be called with the value of the outgoing data
   *        port 'power_assessment'.
   */
  def check_concrete_output(power_assessment: Power_Propulsion_Availability_Supervisor.PowerAssessment.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val power_assessmentValue: Power_Propulsion_Availability_Supervisor.PowerAssessment.Type = get_power_assessment().get
    if(!power_assessment(power_assessmentValue)) {
      testFailures = testFailures :+ st"'power_assessment' did not match expected: value of the outgoing data port is ${power_assessmentValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_power_evidence(value : Power_Propulsion_Availability_Supervisor.PowerEvidence): Unit = {
    Art.insertInInfrastructurePort(Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_management_assessment.operational_api.power_evidence_Id, Power_Propulsion_Availability_Supervisor.PowerEvidence_Payload(value))
  }

  // getter for out DataPort
  def get_power_assessment(): Option[Power_Propulsion_Availability_Supervisor.PowerAssessment.Type] = {
    val value: Option[Power_Propulsion_Availability_Supervisor.PowerAssessment.Type] = get_power_assessment_payload() match {
      case Some(Power_Propulsion_Availability_Supervisor.PowerAssessment_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port power_assessment.  Expecting 'Power_Propulsion_Availability_Supervisor.PowerAssessment_Payload' but received ${v}")
      case _ => None[Power_Propulsion_Availability_Supervisor.PowerAssessment.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_power_assessment_payload(): Option[Power_Propulsion_Availability_Supervisor.PowerAssessment_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.PowerPropulsionAvailabilitySystem_Instance_supervisor_process_power_management_assessment.initialization_api.power_assessment_Id).asInstanceOf[Option[Power_Propulsion_Availability_Supervisor.PowerAssessment_Payload]]
  }

}
